static C_KZG_RET compute_r_powers_for_verify_cell_kzg_proof_batch(...) {
    size_t input_size = DOMAIN_STR_LENGTH              /* domain sep */
                        + sizeof(uint64_t)             /* FIELD_ELEMENTS_PER_CELL (64) */
                        /* FIELD_ELEMENTS_PER_BLOB (4096) IS ABSENT */
                        + sizeof(uint64_t)             /* num_commitments */
                        + sizeof(uint64_t)             /* num_cells */
                        + (num_commitments * BYTES_PER_COMMITMENT)
                        + (num_cells * sizeof(uint64_t))  /* commitment_indices */
                        + (num_cells * sizeof(uint64_t))  /* cell_indices */
                        + (num_cells * BYTES_PER_CELL)
                        + (num_cells * BYTES_PER_PROOF);
    // Domain separator: RCKZGCBATCH__V1_ (16 bytes) — CORRECTLY included
    // FIELD_ELEMENTS_PER_CELL (64) — CORRECTLY included
    // FIELD_ELEMENTS_PER_BLOB (4096) — MISSING (spec requires it)
    blst_sha256(r_bytes.bytes, bytes, input_size);
}

